pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        vm.assume(caddress != address(0) && caddress.code.length > 0);
        vm.assume(v >= 0 && v <= 1000);
        vm.assume(_decimals <= 18);
        (bool success, ) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), address(0)));
        vm.assume(success);
        (bool success2, bytes memory ret) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), from));
        vm.assume(success2);
        uint fromBalBefore = abi.decode(ret, (uint256));
        uint[] memory toBalsBefore = new uint[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool s, bytes memory r) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), _tos[i]));
            assume(s);
            toBalsBefore[i] = abi.decode(r, (uint256));
        }
        c.transfer(from, caddress, _tos, v, _decimals);
        (bool success3, bytes memory ret2) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), from));
        uint fromBalAfter = abi.decode(ret2, (uint256));
        uint sumToAfter = 0;
        for (uint i = 0; i < _tos.length; i++) {
            (bool s, bytes memory r) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), _tos[i]));
            sumToAfter += abi.decode(r, (uint256));
        }
        uint sumToBefore = 0;
        for (uint i = 0; i < _tos.length; i++) {
            sumToBefore += toBalsBefore[i];
        }
        assertTrue(fromBalBefore + sumToBefore == fromBalAfter + sumToAfter);
    }
}
